import sys

def main():
    data = sys.stdin.read().split()
    m = int(data[0])
    par = {}
    for i in range(m):
        p = int(data[1 + 2 * i])
        c = int(data[2 + 2 * i])
        par.setdefault(c, []).append(p)
    a = int(data[1 + 2 * m])
    b = int(data[2 + 2 * m])

    def anc(x):
        seen = set()
        st = []
        for p in par.get(x, []):
            if p not in seen:
                seen.add(p)
                st.append(p)
        while st:
            u = st.pop()
            for p in par.get(u, []):
                if p not in seen:
                    seen.add(p)
                    st.append(p)
        return seen

    print('true' if anc(a) & anc(b) else 'false')

main()

